def compute(vars):
    alpharetta_sq_ft = vars["v1"]
    charlotte_sq_ft = vars["v2"]

    if charlotte_sq_ft == 0:
        return None

    ratio = alpharetta_sq_ft / charlotte_sq_ft
    return {
        "value": ratio,
        "trace": {
            "alpharetta_sq_ft": alpharetta_sq_ft,
            "charlotte_sq_ft": charlotte_sq_ft,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
